decks.fragmentShader:
varying vec3 vWPos;
uniform vec3 uFocus;
uniform float uHoleOut;
uniform float uHoleIn;
uniform float uOpen;
void main(){
  float _c=dot(normalize(vWPos),uFocus);
  float _h=smoothstep(uHoleOut,uHoleIn,_c);
  diffuseColor.a*=mix(1.0,uOpen,_h);
#include <alphatest_fragment>
}

